WebLink.url:
{!requireScript("/soap/ajax/32.0/connection.js")}
{!requireScript("/support/console/37.0/integration.js")}
sforce.connection.sessionId = '{!$Api.Session_ID}';
var user =sforce.connection.getUserInfo();
var url;

var username = user.userName
var result = sforce.connection.query(
"SELECT ID,Asset_Class__c from User WHERE User.username='" + username + "'");
debugger;
var asset =result.getArray("records")[0].Asset_Class__c;
var tod;
var fecha = new Date(); 
var mes =(fecha.getMonth()+1);
tod =fecha.getDay()+'/'+mes+'/'+fecha.getFullYear();

var accountId = '{!Account.Id}';
var cotactId = '{!Contact.Id}';
if(!cotactId) {
cotactId = '{!Lead.Id}';
}
if(asset != null){
var a = asset.split(';');

if(a.length==1){
url = '/00T/e?what_id='+accountId+'&who_id='+cotactId+'&retURL=%2F'+accountId +'&00Nj0000002R5W3='+a[0]+'&tsk5=BBG/Reuters chat&tsk12=Completed&tsk4='+tod;
}else{
url = '/00T/e?what_id='+accountId+'&who_id='+cotactId+'&retURL=%2F'+accountId+'&tsk5=BBG/Reuters chat&tsk12=Completed&tsk4='+tod;
}
}else{
url = '/00T/e?what_id='+accountId+'&who_id='+cotactId+'&retURL=%2F'+accountId+'&tsk5=BBG/Reuters chat&tsk12=Completed&tsk4='+tod;
}

 if (sforce.console.isInConsole()) { 
openSubTab(url, 'New BBG/Reuters chat', true);
} else { 
window.parent.location.assign(url); 
}

function openSubTab(url, title, refreshOnClose) {
	var refreshPrimaryTab = function() {
	sforce.console.getEnclosingPrimaryTabId(function(result) { 
	sforce.console.refreshPrimaryTabById(result.id, true);
	});
}

sforce.console.getEnclosingPrimaryTabId(function(result) { 
	var primaryTabId = result.id; 
	sforce.console.openSubtab(primaryTabId, url, true, title, null, function(r) {
	if (refreshOnClose)
		sforce.console.addEventListener(sforce.console.ConsoleEvent.CLOSE_TAB,
		refreshPrimaryTab, {tabId: r.id});
	}); 
});

}
